-- Keep sheet-defined Alliance and Horde NPCs out of combat.
UPDATE creature_template
SET unit_flags = unit_flags | 131842
WHERE entry IN (2804, 3370, 4974, 5188, 5193, 9988, 11069, 14981);

-- Remove vendor inventory and vendor flags from NPCs not listed in the ITEM sheet.
DELETE FROM npc_vendor WHERE entry NOT IN (5188, 5193, 19534, 19536, 19537, 19538, 19539, 19540, 20066, 20205, 20980, 20989, 35364, 35365);
UPDATE creature_template
SET npcflag = npcflag & 4294967055
WHERE (npcflag & 128) <> 0
  AND entry NOT IN (5188, 5193, 19534, 19536, 19537, 19538, 19539, 19540, 20066, 20205, 20980, 20989, 35364, 35365);

-- Remove trainer flags from merchant and quartermaster NPCs, including legacy entries.
UPDATE creature_template
SET npcflag = npcflag & 4294967183
WHERE LOWER(subname) LIKE '%merchant%'
   OR LOWER(subname) LIKE '%quartermaster%';

UPDATE creature_template
SET npcflag = (npcflag & 4294967183) | 128,
    faction = 1731
WHERE entry IN (5188, 5193, 19534, 19536, 19537, 19538, 19539, 19540, 20066, 20205, 20980, 20989, 35364, 35365);

DELETE FROM npc_vendor WHERE entry IN (5188, 5193, 19534, 19536, 19537, 19538, 19539, 19540, 20066, 20205, 20980, 20989, 35364, 35365);

-- Remove set bonuses and normalize arena armor for the level 19 bracket.
UPDATE item_template
SET ItemSet = 0,
    subclass = CASE
      WHEN Armor < 50 THEN 1
      WHEN Armor < 100 THEN 2
      ELSE 3
    END
WHERE entry IN (7718, 10153, 13185, 13358, 14552, 15067, 15386, 15513, 16669, 16679, 16701, 16708, 16718, 16729, 16733, 18757, 19394, 19695, 22001, 22008, 22016, 22073, 24457, 25947, 27417, 31712)
  AND class = 4;

-- Mark generated vendor items with an extended cost as refundable through item purchase records.
UPDATE item_template
SET Flags = Flags | 4096
WHERE entry IN (890, 1121, 1318, 1482, 1486, 1935, 2041, 2231, 2256, 2271, 2567, 2933, 3324, 3415, 3761, 3822, 4315, 4320, 4385, 4534, 5191, 5194, 5195, 5199, 5202, 5254, 5404, 5815, 5970, 6087, 6226, 6282, 6319, 6414, 6459, 6460, 6465, 6468, 6469, 6472, 6473, 6504, 6505, 6633, 7001, 7002, 7003, 7230, 7718, 8068, 10043, 10153, 10399, 10403, 10410, 10411, 10412, 10413, 10654, 10657, 12982, 12987, 12990, 12994, 12997, 13185, 13358, 14147, 14148, 14552, 15067, 15386, 15513, 16669, 16679, 16701, 16708, 16718, 16729, 16733, 16768, 16987, 17046, 18757, 19394, 19695, 19969, 19972, 20425, 20426, 20427, 20428, 20429, 20430, 20431, 20434, 20437, 20438, 20439, 20440, 20441, 20442, 20443, 20444, 21933, 22001, 22008, 22016, 22073, 22459, 23530, 24033, 24457, 24551, 25829, 25947, 27417, 31174, 31712, 32196, 38839, 38853, 38854, 38855, 38858, 38859, 38860, 38861, 38862, 38863, 38865, 38866, 38870, 38871, 38872, 38873, 38879, 38880, 38881, 38882, 38883, 38884, 38890, 38893, 38896, 38921, 38929, 38933, 38934, 38936, 38946, 39900, 39905, 39906, 39912, 39914, 39915, 39918, 39920, 39927, 44115, 45626, 51809);

-- Normalize arena vendor items by removing random enchants, sockets, and faction-only flags.
UPDATE item_template
SET RandomProperty = 0,
    RandomSuffix = 0,
    socketColor_1 = 0,
    socketColor_2 = 0,
    socketColor_3 = 0,
    socketContent_1 = 0,
    socketContent_2 = 0,
    socketContent_3 = 0,
    socketBonus = 0,
    FlagsExtra = FlagsExtra & 4294967292
WHERE entry IN (7718, 10153, 13185, 13358, 14552, 15067, 15386, 15513, 16669, 16679, 16701, 16708, 16718, 16729, 16733, 18757, 19394, 19695, 22001, 22008, 22016, 22073, 24457, 25947, 27417, 31712);

-- Apply sheet-defined class restrictions to arena vendor items.
